pub async fn fabric_storage_file_closure(root: Rc<FabricStorageOperations>, name: String, bound: Nat, filesystem: &Filesystem) -> std::result::Result<Rc<FabricClosureRead>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*fabric_storage_file_head(root.clone(), name, filesystem).await?).clone() {
    FabricHeadRead::FabricHeadReadRefused { fault: f, .. } => Rc::new(FabricClosureRead::FabricClosureRefused {
    fault: f.clone(),
}),
    FabricHeadRead::FabricHeadObserved { reading: ref __rc_reading, .. } => { match __rc_reading.as_ref() {
    FabricHeadReading::FabricHeadAbsent => Rc::new(FabricClosureRead::FabricClosureRead {
    reading: Rc::new(FabricHeadReading::FabricHeadAbsent),
    newest_first: Rc::new(vec![]),
}),
    FabricHeadReading::FabricHeadAt { object: h, generation: g, .. } => {
        let st = closure_pump(root.clone(), Rc::new(ClosureState {
    pending: Rc::new(vec![h.clone()]),
    newest_first: Rc::new(vec![]),
    seen: v1_rt::rc_empty_set::<String>(),
    refused: std::option::Option::None,
}), 0, bound.clone(), filesystem).await?;
match st.refused.clone() {
    Some(f) => Rc::new(FabricClosureRead::FabricClosureRefused {
    fault: f.clone(),
}),
    std::option::Option::None => match st.pending.clone().first().cloned() {
    Some(at) => Rc::new(FabricClosureRead::FabricClosureBudgetExhausted {
    at: at.clone(),
    bound: bound.clone(),
}),
    std::option::Option::None => Rc::new(FabricClosureRead::FabricClosureRead {
    reading: Rc::new(FabricHeadReading::FabricHeadAt {
    object: h.clone(),
    generation: g.clone(),
}),
    newest_first: st.newest_first.clone(),
}),
},
}
},
} },
})
}
